import { Database } from "bun:sqlite";
import { SecondLayer } from "@secondlayer/sdk";

const db = new Database("transfers.sqlite");
db.run(`create table if not exists transfers (
  cursor text primary key,
  block_height integer not null,
  sender text not null,
  recipient text not null,
  amount text not null
)`);
db.run(
	"create table if not exists checkpoint (id integer primary key check (id = 1), cursor text)",
);

const sl = new SecondLayer({
	apiKey: process.env.SECONDLAYER_API_KEY,
});
const saved = db
	.query<{ cursor: string | null }, []>("select cursor from checkpoint")
	.get();

await sl.streams.events.consume({
	types: ["ft_transfer"],
	// !callout[/fromCursor/] Null on the first run, so the sweep starts at the beginning.
	fromCursor: saved?.cursor ?? null,
	onBatch: (events, _envelope, ctx) => {
		db.transaction(() => {
			for (const event of events) {
				if (event.event_type !== "ft_transfer") continue;
				db.query("insert or replace into transfers values (?, ?, ?, ?, ?)").run(
					event.cursor,
					event.block_height,
					event.payload.sender,
					event.payload.recipient,
					event.payload.amount,
				);
			}
			// !callout[/ctx.cursor/] Commit the checkpoint in the same transaction as the rows.
			db.query("insert or replace into checkpoint values (1, ?)").run(
				ctx.cursor,
			);
		})();
		return ctx.cursor;
	},
	onReorg: (reorg, ctx) => {
		db.transaction(() => {
			// !callout[/>=/] The fork block itself is replaced, so delete from it upward.
			db.query("delete from transfers where block_height >= ?").run(
				reorg.fork_point_height,
			);
			db.query("insert or replace into checkpoint values (1, ?)").run(
				ctx.cursor,
			);
		})();
	},
});

import { SecondLayer } from "@secondlayer/sdk";

const sl = new SecondLayer({
	apiKey: process.env.SECONDLAYER_API_KEY,
	dumpsBaseUrl: process.env.STREAMS_DUMPS_BASE_URL,
});

const result = await sl.streams.events.replay({
	from: "genesis",
	// !callout[/bounded/] Return at the first empty page instead of tailing forever.
	mode: "bounded",
	onDumpFile: async (file, { from }) => {
		// !callout[/download/] Checks the file's sha256 against the signed manifest.
		const bytes = await sl.streams.dumps.download(file);
		await Bun.write(`dumps/${file.from_block}-${file.to_block}.parquet`, bytes);
		// !callout[/from/] Set on a resume. A file that straddles it arrives whole, so skip rows at or below it.
		console.log(`dump ${file.path}, resume after ${from ?? "genesis"}`);
	},
	onBatch: (events, envelope) => {
		console.log(`live page: ${events.length} events`);
		return envelope.next_cursor;
	},
});

console.log(`caught up at ${result.cursor} after ${result.pages} live pages`);

import { SecondLayer } from "@secondlayer/sdk";

const sl = new SecondLayer({
	apiKey: process.env.SECONDLAYER_API_KEY,
});

const subscription = sl.streams.events.subscribe({
	types: ["print"],
	contractId: "SM3VDXK3WZZSA84XXFKAFAF15NNZX32CTSG82JFQ4.sbtc-registry",
	onEvent: (event) => {
		// !callout[/event_type/] Each event is a union until you check its type.
		if (event.event_type !== "print") return;
		console.log(event.cursor, event.payload.topic);
	},
	// !callout[/onError/] Transport errors reconnect from the last handled cursor; this just observes them.
	onError: (err) => console.error("subscription error", err),
});

// Calling the subscription unsubscribes.
process.on("SIGTERM", () => subscription());

// !callout[/done/] Settles when the loop ends, and rejects on an error a retry cannot fix.
await subscription.done;
